  @Test
  def testGetDailyEnergyXmlTag(): Unit = {
    df.rdd.foreach(row => {
      val dailyEnergyXmlTag = StoriciFlow.getDailyEnergyXmlTag(row)
      if (dailyEnergyXmlTag._1 != -1) { // entries con dataMisura corretta
//        println(dailyEnergyXmlTag._2)
        if (!row.getAs[String](StoriciSchema.data_misura).equals("31/10/2021") && !row.getAs[String](StoriciSchema.data_misura).equals("27/03/2022")) { // tutti i giorni tranne le due transizioni DST
          Assert.assertEquals(row.getAs[String](StoriciSchema.data_misura).take(2), XML.loadString(dailyEnergyXmlTag._2).text)
          val printer = new scala.xml.PrettyPrinter(1000000, 2)
          Assert.assertTrue(printer.format(XML.loadString(dailyEnergyXmlTag._2)).indexOf("E1") > printer.format(XML.loadString(dailyEnergyXmlTag._2)).indexOf("E96"))
        }

        Assert.assertTrue(dailyEnergyXmlTag._2.startsWith("<" + StoriciXMLSchema.Ea))
        Assert.assertTrue(dailyEnergyXmlTag._2.endsWith("</" + StoriciXMLSchema.Ea + ">"))

        if (row.getAs[String](StoriciSchema.data_misura).equals("31/10/2021")) { // giorno di transizione DST
          Assert.assertTrue(dailyEnergyXmlTag._2.contains("<Ea Dst=" + "\"" + "2" + "\""))
          Assert.assertTrue(dailyEnergyXmlTag._2.contains("<Ea Dst=" + "\"" + "3" + "\""))
          Assert.assertTrue(dailyEnergyXmlTag._2.count(char => char == 'E') == 104) // 1 + 12 + 1 + 1 + 88 + 1
        }
        if (row.getAs[String](StoriciSchema.data_misura).equals("27/03/2022")) { // giorno di transizione DST
          Assert.assertTrue(dailyEnergyXmlTag._2.contains("<Ea Dst=" + "\"" + "1" + "\""))
          println(dailyEnergyXmlTag._2)
          println(dailyEnergyXmlTag._2.count(char => char == 'E'))
          Assert.assertTrue(dailyEnergyXmlTag._2.count(char => char == 'E') == 94) // 1 + 92 + 1
        }

      }
    })

    Assert.assertEquals(1, df.rdd.map(row => StoriciFlow.getDailyEnergyXmlTag(row)._1).filter(day => day == -1).count) // controllo presenza di entry con data errata
    Assert.assertEquals(2, df.rdd.map(row => StoriciFlow.getDailyEnergyXmlTag(row)._2.count(char => char == 'E')).filter(count => count == 94).count) // controllo presenza di entry con misure errate -> "", "NULL", "null", null (1 + 96 + 1 - 4 = 94), contata anche una entry che ha giornata di transizione DST 2022-03-27
    Assert.assertEquals(df.count - 4, df.rdd.map(row => StoriciFlow.getDailyEnergyXmlTag(row)._2.count(char => char == 'E')).filter(count => count == 98).count) // (1 + 96 + 1 = 98)
  }

