  @Test
  def testGetDayType(): Unit = {
    val listTransizione1: List[String] = List("2020-03-29", "2021-03-28", "2022-03-27")
    listTransizione1.map(data => LocalDate.parse(data)).map(data => StoriciFlow.getDayType(data)).count(dataType => dataType == 1).equals(listTransizione1.length)

    val listTransizione2: List[String] = List("2019-10-27", "2020-10-25", "2021-10-31")
    listTransizione2.map(data => LocalDate.parse(data)).map(data => StoriciFlow.getDayType(data)).count(dataType => dataType == 2).equals(listTransizione2.length)

    val listNoTransizione: List[String] = List("2021-02-27", "2020-08-16", "2022-05-15")
    listNoTransizione.map(data => LocalDate.parse(data)).map(data => StoriciFlow.getDayType(data)).count(dataType => dataType == 0).equals(listNoTransizione.length)
  }

